import * as bytes from "std/bytes";
import * as cli from "std/cli";
import * as fs from "std/fs";
import * as json from "std/json";
import * as path from "std/path";

import * as tree from "local/marimay-manifest/tree";

type Manifest {
  public version: int,
  public entries: []tree.Entry,
}

fn index(value: Manifest): Result<Map<string, tree.Entry>, string> {
  if value.version != 1 {
    return Err("Ожидается версия манифеста 1");
  }
  const entries = mapOf<string, tree.Entry>();
  for entry in value.entries {
    const _ = tree.relative(entry.path)?;
    if entry.kind != "file"
      && entry.kind != "directory"
      && entry.kind != "symlink"
      && entry.kind != "other" {
      return Err($"{entry.path}: неизвестный тип записи");
    }
    if entry.size < 0 || (entry.kind != "file" && entry.size != 0) {
      return Err($"{entry.path}: недопустимый размер");
    }
    if entries.containsKey(entry.path) {
      return Err($"{entry.path}: повтор пути");
    }
    const _ = entries.put(entry.path, entry).mapError(
      (error) => "Слишком много записей манифеста",
    )?;
  }
  return Ok(entries);
}

fn differences(expected: Manifest, actual: []tree.Entry): Result<[]string, string> {
  const remaining = index(expected)?;
  const result: []string = [];
  for entry in actual {
    if const previous = remaining.remove(entry.path) {
      if previous.kind != entry.kind || previous.size != entry.size {
        result.push(
          $"Изменено: {entry.path} (ожидалось {previous.kind}, {previous.size}; получено {entry.kind}, {entry.size})",
        ).mapError((error) => "Слишком много различий")?;
      }
    } else {
      result.push($"Добавлено: {entry.path}").mapError((error) => "Слишком много различий")?;
    }
  }
  // Sort missing entries independently of input manifest order.
  const missing: []tree.Entry = [];
  for pair in remaining {
    match pair {
      (name, entry) => {
        missing.push(entry).mapError((error) => "Слишком много различий")?;
      },
    };
  }
  tree.sort(missing)?;
  for entry in missing {
    result.push($"Отсутствует: {entry.path}").mapError((error) => "Слишком много различий")?;
  }
  return Ok(result);
}

fn execute(parsed: cli.Parsed, positions: []string): Result<int, string> {
  const limit = number(parsed, "max-entries", 10000, 65536)?;
  const depth = number(parsed, "max-depth", 64, 256)?;
  const root = path.fromString(positions[1]).mapError((error) => "Недопустимый корень")?;
  const scanned = tree.walk(root, limit, depth)?;
  if scanned.issues.length() != 0 {
    const issue = scanned.issues[0];
    return Err($"{issue.path}: {issue.message}");
  }
  if positions[0] == "generate" {
    const encoded = json.encode(Manifest { version: 1, entries: scanned.entries }).mapError(
      json.message,
    )?;
    if const output = option(parsed, "output") {
      const destination = path.fromString(output).mapError(
        (error) => "Недопустимый выходной путь",
      )?;
      fs.writeBytes(destination, encoded).mapError(fs.message)?;
    } else {
      emit(bytes.decodeUtf8(encoded).mapError((error) => "Некорректный UTF-8 результата")?)?;
    }
    flush()?;
    return Ok(0);
  }
  const input = path.fromString(positions[2]).mapError((error) => "Недопустимый путь манифеста")?;
  const expected = json.decode<Manifest>(
    fs.readBytes(input, 1048576).mapError(fs.message)?,
  ).mapError(json.message)?;
  const changes = differences(expected, scanned.entries)?;
  for change in changes {
    emit(change)?;
  }
  if changes.length() == 0 {
    emit("Совпадает")?;
  }
  flush()?;
  return Ok(
    match changes.length() == 0 {
      true => 0,
      false => 1,
    },
  );
}

fn main(arguments: []string): int {
  const parser = match cli.newParser(
    "marimay-manifest",
    "Создать или проверить JSON-инвентарь дерева; ссылки не обходятся.",
    [
      cli.flagOption("help", Some("h"), false, false, "Показать справку"),
      cli.requiredValueOption(
        "output",
        None,
        "ФАЙЛ",
        false,
        false,
        "Атомарно записать generate в файл",
      ),
      cli.requiredValueOption(
        "max-entries",
        None,
        "N",
        false,
        false,
        "0..65536; по умолчанию 10000",
      ),
      cli.requiredValueOption("max-depth", None, "N", false, false, "0..256; по умолчанию 64"),
    ],
    [cli.positional("arguments", false, true, "generate КОРЕНЬ | verify КОРЕНЬ МАНИФЕСТ")],
    cli.defaultLimits(),
  ) {
    Ok(value) => value,
    Err(error) => {
      return fail("marimay-manifest", cli.message(error), 2);
    },
  };
  const parsed = match cli.parse(parser, arguments) {
    Ok(value) => value,
    Err(error) => {
      return fail("marimay-manifest", cli.message(error), 2);
    },
  };
  if cli.count(parsed, "help") != 0 {
    return match emit(
      match cli.help(parser, 80) {
        Ok(value) => value,
        Err(error) => {
          return fail("marimay-manifest", cli.message(error), 2);
        },
      },
    ) {
      Ok(_) => match flush() {
        Ok(_) => 0,
        Err(error) => fail("marimay-manifest", error, 1),
      },
      Err(error) => fail("marimay-manifest", error, 1),
    };
  }
  const positions = cli.positionalValues(parsed, "arguments");
  if positions.length() < 2 {
    return fail("marimay-manifest", "Нужно generate КОРЕНЬ или verify КОРЕНЬ МАНИФЕСТ", 2);
  }
  if (positions[0] == "generate" && positions.length() != 2)
    || (positions[0] == "verify" && (positions.length() != 3 || cli.count(parsed, "output") != 0))
    || (positions[0] != "generate" && positions[0] != "verify") {
    return fail(
      "marimay-manifest",
      "Нужно generate КОРЕНЬ [--output ФАЙЛ] или verify КОРЕНЬ МАНИФЕСТ",
      2,
    );
  }
  return match execute(parsed, positions) {
    Ok(status) => status,
    Err(error) => fail("marimay-manifest", error, 2),
  };
}

