import * as path from "std/path";

import * as tree from "local/marimay-manifest/tree";

@test
fn orderingPreservesIdentityAndUtf8Order(): void {
  const first = tree.Entry { path: "a/x", kind: "file", size: 2 };
  const entries = [
    first,
    tree.Entry { path: "я", kind: "directory", size: 0 },
    tree.Entry { path: "a.txt", kind: "file", size: 1 },
    tree.Entry { path: "a", kind: "directory", size: 0 },
  ];
  const alias = entries;
  expect.ok(tree.sort(entries));
  expect.equal(alias[0].path, "a");
  expect.equal(alias[1].path, "a.txt");
  expect.equal(alias[2].path, "a/x");
  expect.equal(alias[3].path, "я");
  expect.equal(identity.same(alias[2], first), true);
  const empty: []tree.Entry = [];
  expect.ok(tree.sort(empty));
  expect.equal(empty.length(), 0);
}

@test
fn relativePathsStayInsideRoot(): void {
  expect.equal(tree.relative("папка/файл"), Ok("папка/файл"));
  for name in ["", ".", "..", "../file", "/file", "a/../b", "a//b"] {
    expect.err(tree.relative(name));
  }
}

@test
fn malformedInventoriesAreRejected(): void {
  const entry = tree.Entry { path: "a", kind: "file", size: 1 };
  expect.err(index(Manifest { version: 2, entries: [] }));
  expect.err(index(Manifest { version: 1, entries: [entry, entry] }));
  expect.err(
    index(Manifest { version: 1, entries: [tree.Entry { path: "a", kind: "file", size: -1 }] }),
  );
  expect.err(
    index(Manifest { version: 1, entries: [tree.Entry { path: "a", kind: "directory", size: 1 }] }),
  );
  expect.err(
    index(Manifest { version: 1, entries: [tree.Entry { path: "../a", kind: "file", size: 1 }] }),
  );
}

@test
fn differencesAreDeterministicAndDoNotMutateInput(): void {
  const old = [
    tree.Entry { path: "z", kind: "file", size: 0 },
    tree.Entry { path: "a", kind: "file", size: 2 },
    tree.Entry { path: "m", kind: "file", size: 1 },
  ];
  const expected = Manifest { version: 1, entries: old };
  const changes = match differences(
    expected,
    [
      tree.Entry { path: "b", kind: "file", size: 0 },
      tree.Entry { path: "m", kind: "file", size: 4 },
    ],
  ) {
    Ok(value) => value,
    Err(error) => panic(error),
  };
  expect.equal(changes.length(), 4);
  expect.equal(changes[0], "Добавлено: b");
  expect.equal(changes[2], "Отсутствует: a");
  expect.equal(changes[3], "Отсутствует: z");
  expect.equal(old[0].path, "z");
  expect.equal(old.length(), 3);
}

@test
fn traversalLimitsAreValidatedBeforeIo(): void {
  const root = match path.fromString(".") {
    Ok(value) => value,
    Err(_) => panic("path"),
  };
  for limit in [-1, 65537] {
    expect.equal(
      match tree.walk(root, limit, 1) {
        Err(error) => error,
        Ok(_) => "unexpected",
      },
      "Недопустимые границы обхода",
    );
  }
  for depth in [-1, 257] {
    expect.equal(
      match tree.walk(root, 1, depth) {
        Err(error) => error,
        Ok(_) => "unexpected",
      },
      "Недопустимые границы обхода",
    );
  }
}

