import * as cli from "std/cli";
import * as env from "std/env";
import * as json from "std/json";
import * as path from "std/path";
import * as process from "std/process";

type Variable {
  public name: string,
  public state: string,
  public value: string,
  public error: string,
}

type PathInfo {
  public input: string,
  public normalized: string,
  public absolute: bool,
  public error: string,
}

type Report {
  public ok: bool,
  public context: bool,
  public directory: string,
  public variables: []Variable,
  public paths: []PathInfo,
}

fn variable(name: string): Variable {
  return match env.get(name) {
    Ok(Some(value)) => Variable { name, state: "present", value, error: "" },
    Ok(None) => Variable { name, state: "absent", value: "", error: "" },
    Err(error) => Variable { name, state: "error", value: "", error: env.message(error) },
  };
}

fn pathInfo(input: string): PathInfo {
  return match path.fromString(input) {
    Ok(value) => PathInfo {
      input,
      normalized: path.string(value),
      absolute: path.isAbsolute(value),
      error: "",
    },
    Err(_) => PathInfo { input, normalized: "", absolute: false, error: "Недопустимый путь" },
  };
}

fn collect(parsed: cli.Parsed): Result<Report, string> {
  const variables: []Variable = [];
  const paths: []PathInfo = [];
  let ok = true;
  let directory = "";
  const names = setOf<string>();
  if cli.count(parsed, "context") != 0 {
    directory = path.string(process.currentDirectory().mapError(process.message)?);
  }
  for occurrence in cli.occurrences(parsed, "env") {
    if const name = occurrence {
      // One lookup per explicit name, retaining request order.
      if !names.contains(name) {
        const _ = names.add(name).mapError((error) => "Слишком много переменных")?;
        const result = variable(name);
        ok = ok && result.state != "error";
        variables.push(result).mapError((error) => "Слишком много переменных")?;
      }
    }
  }
  for occurrence in cli.occurrences(parsed, "path") {
    if const input = occurrence {
      const result = pathInfo(input);
      ok = ok && result.error == "";
      paths.push(result).mapError((error) => "Слишком много путей")?;
    }
  }
  return Ok(Report { ok, context: cli.count(parsed, "context") != 0, directory, variables, paths });
}

fn execute(parsed: cli.Parsed): Result<int, string> {
  const report = collect(parsed)?;
  const encoded = json.encode(report).mapError(json.message)?;
  emit(bytes.decodeUtf8(encoded).mapError((error) => "Некорректный UTF-8 результата")?)?;
  flush()?;
  return Ok(
    match report.ok {
      true => 0,
      false => 1,
    },
  );
}

fn main(arguments: []string): int {
  const parser = match cli.newParser(
    "marimay-env-paths",
    "Объяснить выбранные пути и явно названные переменные; JSON-отчёт.",
    [
      cli.flagOption("help", Some("h"), false, false, "Показать справку"),
      cli.flagOption("context", None, false, false, "Показать текущий рабочий каталог"),
      cli.requiredValueOption(
        "env",
        None,
        "ИМЯ",
        false,
        true,
        "Прочитать только эту переменную с env.read capability",
      ),
      cli.requiredValueOption(
        "path",
        None,
        "ПУТЬ",
        false,
        true,
        "Лексически нормализовать путь без доступа к файлам",
      ),
    ],
    [],
    cli.defaultLimits(),
  ) {
    Ok(value) => value,
    Err(error) => {
      return fail("marimay-env-paths", cli.message(error), 2);
    },
  };
  const parsed = match cli.parse(parser, arguments) {
    Ok(value) => value,
    Err(error) => {
      return fail("marimay-env-paths", cli.message(error), 2);
    },
  };
  if cli.count(parsed, "help") != 0 {
    const help = match cli.help(parser, 80) {
      Ok(value) => value,
      Err(error) => {
        return fail("marimay-env-paths", cli.message(error), 2);
      },
    };
    return match emit(help) {
      Ok(_) => match flush() {
        Ok(_) => 0,
        Err(error) => fail("marimay-env-paths", error, 2),
      },
      Err(error) => fail("marimay-env-paths", error, 2),
    };
  }
  if cli.count(parsed, "env") + cli.count(parsed, "path") + cli.count(parsed, "context") == 0 {
    return fail("marimay-env-paths", "Нужно --env ИМЯ, --path ПУТЬ или --context", 2);
  }
  return match execute(parsed) {
    Ok(status) => status,
    Err(error) => fail("marimay-env-paths", error, 2),
  };
}

