@test
fn selectedDeniedValuesStayRedacted(): void {
  const result = variable("MMAY_FILE_WAVE_UNDECLARED");
  expect.equal(result.state, "error");
  expect.equal(result.value, "");
  expect.equal(result.error, "environment variable MMAY_FILE_WAVE_UNDECLARED is not allowed");
}

@test
fn invalidNamesAreSeparateFromMissing(): void {
  const result = variable("BAD-NAME");
  expect.equal(result.state, "error");
  expect.equal(result.value, "");
  expect.equal(result.error, "invalid environment variable name");
}

@test
fn pathsNormalizeWithoutFilesystemAccess(): void {
  const result = pathInfo("a/../папка//./file");
  expect.equal(result.normalized, "папка/file");
  expect.equal(result.absolute, false);
  expect.equal(result.error, "");
  expect.equal(pathInfo("").normalized, ".");
  expect.equal(pathInfo("/..").error, "Недопустимый путь");
  expect.equal(pathInfo("a\0b").error, "Недопустимый путь");
}

